import{H as e,_t as t,nt as n,rt as r}from"./chunks/framework.ByJSXnli.js";var i=JSON.parse(`{"title":"Writing documentation","description":"","frontmatter":{},"headers":[],"relativePath":"contributing/writing-documentation.md","filePath":"contributing/writing-documentation.md"}`),a={name:`contributing/writing-documentation.md`};function o(e,i,a,o,s,c){return t(),n(`div`,null,[...i[0]||=[r(`<h1 id="writing-documentation" tabindex="-1">Writing documentation <a class="header-anchor" href="#writing-documentation" aria-label="Permalink to “Writing documentation”">​</a></h1><p>This site is built with VitePress from the <code>docs</code> folder. Run <code>npm run docs:dev</code> to see a change while you write.</p><h2 id="choose-the-section" tabindex="-1">Choose the section <a class="header-anchor" href="#choose-the-section" aria-label="Permalink to “Choose the section”">​</a></h2><div class="doc-table-scroll" tabindex="0"><table><thead><tr><th>Section</th><th>Readers</th><th>Holds</th></tr></thead><tbody><tr><td>Guide</td><td>Users who configure and run algorithms</td><td>Concepts and tasks, in reading order</td></tr><tr><td>Examples</td><td>Users who want a complete program</td><td>One task from start to result</td></tr><tr><td>Extend</td><td>Users who write their own components</td><td>Authoring contracts and walkthroughs</td></tr><tr><td>Reference</td><td>Anyone looking something up</td><td>The glossary and catalogs</td></tr><tr><td>Contributing</td><td>People who change the library</td><td>Rules, architecture and workflow</td></tr></tbody></table></div><p>A page belongs to one section. Link to a page in another section rather than repeating it. Features of the Experimental package get no page. Describe them in the XML remarks of their code.</p><h2 id="write-the-text" tabindex="-1">Write the text <a class="header-anchor" href="#write-the-text" aria-label="Permalink to “Write the text”">​</a></h2><ul><li>Describe how the library works today. Do not write that it &quot;now&quot; works some way, and leave design history to the issues.</li><li>Use the terms of the <a href="/reference/glossary.html">glossary</a>.</li><li>Keep sentences short. Use no semicolons. Split the sentence instead.</li><li>Start a page with what the reader can do with it, in one or two sentences.</li><li>End a Guide page with the next page of the guide.</li></ul><h2 id="show-code-that-runs" tabindex="-1">Show code that runs <a class="header-anchor" href="#show-code-that-runs" aria-label="Permalink to “Show code that runs”">​</a></h2><p>Code on a page comes from <code>test/HeuristicLib.Tests.Docs</code>. Mark the shown part with a named region and import it:</p><div class="language-md line-numbers-mode"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">md</span><pre class="shiki shiki-themes light-plus dark-plus" style="--shiki-light:#000000;--shiki-dark:#D4D4D4;--shiki-light-bg:#FFFFFF;--shiki-dark-bg:#1E1E1E;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#000000;--shiki-dark:#D4D4D4;">&lt;&lt;&lt; ../../test/HeuristicLib.Tests.Docs/Extending/AlgorithmAuthoringDocumentationSpecs.cs#iterative-algorithm-type{csharp}</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>The suite compiles and runs that code, and the build fails when a path or region is missing. A fenced code block is not checked, so keep those to short excerpts.</p><ul><li>Keep test attributes and assertions outside the region.</li><li>Give methods a block body, as <a href="/contributing/developer-guidelines.html">developer guidelines</a> § 10.3 states.</li><li>Put <code>Parameter</code> declarations in a second part of a <code>partial record</code>. Show them in a collapsed <code>::: details</code> block, so the first part shows what the component does.</li><li>When a page quotes output, the spec asserts the same text.</li><li>Output that differs between processors, such as a tree that genetic programming finds, is shown as an example. The spec asserts its properties instead, such as an error below a bound, and compares computed numbers with a tolerance.</li></ul><h2 id="add-a-figure" tabindex="-1">Add a figure <a class="header-anchor" href="#add-a-figure" aria-label="Permalink to “Add a figure”">​</a></h2><p>A chart reads its data from <code>docs/.vitepress/figure-data</code>. A documentation spec computes that data and calls <code>FigureData.Write</code>, which writes the file on every run. When a change to the library alters a documented run, the file changes in your working tree. Commit it with the change, together with any output or caption the page quotes from that run, so the pull request review sees it.</p><p>Each figure has a settings file in <code>docs/.vitepress/figures</code> that imports its data and says how to draw it. The page imports the settings file and passes it to a component, with the caption as content:</p><div class="language-md line-numbers-mode"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">md</span><pre class="shiki shiki-themes light-plus dark-plus" style="--shiki-light:#000000;--shiki-dark:#D4D4D4;--shiki-light-bg:#FFFFFF;--shiki-dark-bg:#1E1E1E;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#000000;--shiki-dark:#D4D4D4;">&lt;script setup&gt;</span></span>
<span class="line"><span style="--shiki-light:#000000;--shiki-dark:#D4D4D4;">import convergence from &quot;../.vitepress/figures/getting-started-convergence&quot;;</span></span>
<span class="line"><span style="--shiki-light:#000000;--shiki-dark:#D4D4D4;">&lt;/script&gt;</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#000000;--shiki-dark:#D4D4D4;">&lt;LineChart v-bind=&quot;convergence&quot;&gt;Caption text.&lt;/LineChart&gt;</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br></div></div><p>Every chart offers its data as a table, so a reader who cannot see the chart can still read it.</p><p>The charts <code>LineChart</code>, <code>ScatterChart</code>, <code>TourPanels</code> and <code>ExperimentGrid</code> take a settings file. <code>ExpressionFit</code> reads its data file itself, and <code>CapacityBars</code> draws the numbers its page quotes. The other components are diagrams that take only a caption. All live in <code>docs/.vitepress/theme/figures</code> and draw with the <code>--hl-fig-*</code> color tokens of <code>figures.css</code>, which have light and dark values.</p><h2 id="keep-the-catalogs-complete" tabindex="-1">Keep the catalogs complete <a class="header-anchor" href="#keep-the-catalogs-complete" aria-label="Permalink to “Keep the catalogs complete”">​</a></h2><p>The <a href="/reference/operators.html">operator</a> and <a href="/reference/algorithms.html">algorithm</a> catalogs list every public type of the core package. <code>ReferenceCatalogDocumentationSpecs</code> fails when a type is missing or a row names a type that does not exist. Add a row when you add an operator or an algorithm.</p><h2 id="check-the-change" tabindex="-1">Check the change <a class="header-anchor" href="#check-the-change" aria-label="Permalink to “Check the change”">​</a></h2><div class="language-console line-numbers-mode"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">console</span><pre class="shiki shiki-themes light-plus dark-plus" style="--shiki-light:#000000;--shiki-dark:#D4D4D4;--shiki-light-bg:#FFFFFF;--shiki-dark-bg:#1E1E1E;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#000000;--shiki-dark:#D4D4D4;">dotnet test --project test/HeuristicLib.Tests.Docs/HeuristicLib.Tests.Docs.csproj --configuration Release --no-restore</span></span>
<span class="line"><span style="--shiki-light:#000000;--shiki-dark:#D4D4D4;">npm run docs:build</span></span>
<span class="line"><span style="--shiki-light:#000000;--shiki-dark:#D4D4D4;">npx --no-install prettier --check docs</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div>`,22)]])}var s=e(a,[[`render`,o]]);export{i as __pageData,s as default};